def is_valid_simple_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or local[0] == '.' or local[-1] == '.':
        return False
    local_parts = local.split('.')
    if any(p == '' for p in local_parts):
        return False
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_+-')
    if not all(all(c in allowed for c in p) for p in local_parts):
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if len(label) == 0 or label[0] == '-' or label[-1] == '-':
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    tld = labels[-1]
    return len(tld) >= 2 and tld.isalpha()

