from collections import defaultdict

def group_anagrams(words):
    def signature(w):
        counts = [0] * 26
        for c in w:
            counts[ord(c) - ord('a')] += 1
        return tuple(counts)
    groups = defaultdict(list)
    order = []
    for w in words:
        sig = signature(w)
        if sig not in groups:
            order.append(sig)
        groups[sig].append(w)
    return [groups[sig] for sig in order]

