def is_valid_datetime_string(s):
    import re
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})', s)
    if not m:
        return False
    y, mo, d, h, mi, sec = (int(g) for g in m.groups())
    if not (1 <= mo <= 12):
        return False
    leap = (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
    days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not (1 <= d <= days_in_month[mo - 1]):
        return False
    return 0 <= h <= 23 and 0 <= mi <= 59 and 0 <= sec <= 59

