def merged_busy_minutes(intervals):
    if not intervals:
        return 0
    max_end = max(e for s, e in intervals)
    covered = [False] * max_end
    for s, e in intervals:
        for minute in range(s, e):
            covered[minute] = True
    return sum(covered)

