def shift_digits_in_string(s, k):
    shift = k % 10
    mapping = {str(d): str((d + shift) % 10) for d in range(10)}
    table = str.maketrans(mapping)
    return s.translate(table)

import re

def is_valid_non_blocked_email(s, blocked_domains):
    m = re.fullmatch(r'([A-Za-z0-9._+-]+)@((?:[A-Za-z0-9-]+\.)+[A-Za-z0-9-]+)', s)
    if not m:
        return False
    domain = m.group(2)
    blocked = {b.lower() for b in blocked_domains}
    return domain.lower() not in blocked

